'use strict';
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const assert = require('assert');
const { pathToFileURL } = require('url');
const root = process.cwd();
const out = path.join(root, '.cvf/runtime/cvf-expense-legibility-local-review-20261010');
const web = path.join(root, 'EXTENSIONS/CVF_v1.6_AGENT_PLATFORM/cvf-web');
const source = path.join(web, 'src/expenses/ExpenseList.tsx');
const hash = p => crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex');
const sourceHash = hash(source);
const longText = 'Reviewer340Light0123456789'.repeat(4);
const rows = [
  { id: 'RV-F', date: '2026-02-27', label: 'Other month', amount: 76543 },
  { id: 'RV-M2', date: '2026-03-29', label: longText, amount: 987654 },
  { id: 'RV-M1', date: '2026-03-02', label: 'Local light contrast probe', amount: 123456 },
  { id: 'RV-BAD', date: '05/03/2026', label: 'Bad date row', amount: 99999 },
];
const luminance = rgb => rgb.map(v => {
  const s = v / 255;
  return s <= 0.04045 ? s / 12.92 : ((s + 0.055) / 1.055) ** 2.4;
}).reduce((v, c, i) => v + c * [0.2126, 0.7152, 0.0722][i], 0);
const contrast = (a, b) => {
  const l = [luminance(a), luminance(b)].sort((x, y) => y - x);
  return (l[0] + 0.05) / (l[1] + 0.05);
};
function requireHeaderContrast(headers) {
  assert.equal(headers.length, 3, 'three measured headers');
  for (const h of headers) assert(contrast(h.color, h.bg) >= 4.5, 'HEADER_TEXT_CONTRAST ' + h.text);
}
async function measure(page) {
  return page.evaluate(() => {
    const cs = el => getComputedStyle(el);
    const rgb = c => c.match(/[\d.]+/g).slice(0, 3).map(Number);
    const rect = el => {
      const r = el.getBoundingClientRect();
      return { left: r.left, right: r.right, top: r.top, bottom: r.bottom, width: r.width, height: r.height };
    };
    const inner = el => {
      const r = rect(el), s = cs(el);
      return { left: r.left + parseFloat(s.paddingLeft) + parseFloat(s.borderLeftWidth), right: r.right - parseFloat(s.paddingRight) - parseFloat(s.borderRightWidth), top: r.top + parseFloat(s.paddingTop) + parseFloat(s.borderTopWidth), bottom: r.bottom - parseFloat(s.paddingBottom) - parseFloat(s.borderBottomWidth) };
    };
    const section = document.querySelector('section'), title = document.querySelector('h2');
    const input = document.querySelector('input'), label = document.querySelector('label');
    const table = document.querySelector('table'), focus = cs(input);
    return {
      ids: [...document.querySelectorAll('[data-expense-id]')].map(el => el.dataset.expenseId),
      headers: [...document.querySelectorAll('th')].map(el => ({ text: el.textContent, color: rgb(cs(el).color), bg: rgb(cs(section).backgroundColor) })),
      cells: [...document.querySelectorAll('th,td')].map(el => {
        const range = document.createRange(); range.selectNodeContents(el);
        return { text: el.textContent, box: rect(el), inner: inner(el), lines: [...range.getClientRects()].map(r => ({ left: r.left, right: r.right, top: r.top, bottom: r.bottom })) };
      }),
      input: rect(input), inputColor: rgb(cs(input).color), inputBackground: rgb(cs(input).backgroundColor),
      labelLinked: label.control === input, labelText: label.textContent, inputType: input.type,
      titleLinked: section.getAttribute('aria-labelledby') === title.id,
      tableLinked: table ? table.getAttribute('aria-labelledby') === title.id : null,
      scopes: [...document.querySelectorAll('th')].map(el => el.getAttribute('scope')),
      section: inner(section), docOverflow: document.documentElement.scrollWidth - innerWidth,
      sectionOverflow: section.scrollWidth - section.clientWidth,
      surface: rgb(cs(section).backgroundColor), page: rgb(cs(document.body).backgroundColor),
      focus: { active: document.activeElement === input, visible: input.matches(':focus-visible'), color: rgb(focus.outlineColor), width: focus.outlineWidth, style: focus.outlineStyle, offset: focus.outlineOffset },
      status: document.querySelector('[role=status]')?.textContent ?? null,
    };
  });
}
const contained = (r, b) => r.left >= b.left - 1 && r.right <= b.right + 1 && r.top >= b.top - 1 && r.bottom <= b.bottom + 1;
function requireLayout(s) {
  assert(s.input.width >= 44 && s.input.height >= 44, 'native touch target');
  assert(s.docOverflow <= 0 && s.sectionOverflow <= 1, 'no horizontal overflow');
  for (const cell of s.cells) {
    assert(contained(cell.box, s.section), 'cell within section');
    for (const line of cell.lines) assert(contained(line, cell.inner), 'full text inside cell');
  }
}
async function requireKeyboard(page) {
  await page.evaluate(() => {
    document.body.setAttribute('tabindex', '-1');
    document.body.focus();
  });
  await page.keyboard.press('Tab');
  const s = await measure(page);
  await page.evaluate(() => document.body.removeAttribute('tabindex'));
  assert(s.focus.active && s.focus.visible, 'keyboard focus on month input');
  assert.deepEqual([s.focus.width, s.focus.style, s.focus.offset], ['2px', 'solid', '2px']);
  assert(contrast(s.focus.color, s.surface) >= 3 && contrast(s.focus.color, s.page) >= 3, 'focus contrast');
  return s.focus;
}
(async () => {
  const entry = path.join(out, 'own-entry.tsx');
  const spec = path.relative(out, source).replace(/\\/g, '/');
  fs.writeFileSync(entry, `import React from 'react';import {createRoot} from 'react-dom/client';import {ExpenseList} from ${JSON.stringify(spec)};createRoot(document.getElementById('root')).render(React.createElement(ExpenseList,{expenses:${JSON.stringify(rows)}}));`);
  const vite = await import(pathToFileURL(path.join(web, 'node_modules/vite/dist/node/index.js')).href);
  const result = await vite.build({ configFile: false, envFile: false, root: out, mode: 'production', logLevel: 'silent', define: { 'process.env.NODE_ENV': '"production"' }, resolve: { alias: ['react-dom', 'react'].map(name => ({ find: name, replacement: path.join(web, 'node_modules', name).replace(/\\/g, '/') })) }, oxc: { jsx: { runtime: 'automatic' } }, build: { write: false, minify: true, sourcemap: false, emptyOutDir: false, lib: { entry, formats: ['iife'], name: 'LocalLegibility' } } });
  const chunks = (Array.isArray(result) ? result : [result]).flatMap(r => r.output);
  assert.equal(chunks.length, 1);
  const html = path.join(out, 'own-340-light.html');
  fs.writeFileSync(html, `<!doctype html><html lang="vi"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>:root{color-scheme:light;--cvf-bg-page:#f8fafc;--cvf-surface:#ffffff;--cvf-text-primary:#0f172a;--cvf-text-secondary:#334155;--cvf-text-muted:#475569;--cvf-border:rgba(15,23,42,.12);--cvf-border-strong:rgba(15,23,42,.24);--cvf-warning:#92400e;--cvf-accent:#5b5cf6}body{margin:0;background:var(--cvf-bg-page);font:16px system-ui}main{padding:16px}:focus-visible{outline:2px solid var(--cvf-accent);outline-offset:2px}</style><main><div id="root"></div></main><script>${chunks[0].code.replace(/<\/(script)/gi, '<\\/$1')}</script></html>`);
  const { chromium } = require(path.join(web, 'node_modules/@playwright/test'));
  const browser = await chromium.launch();
  let report;
  try {
    const context = await browser.newContext({ viewport: { width: 340, height: 844 } });
    try {
      const page = await context.newPage(), external = [], errors = [];
      page.setDefaultTimeout(15000);
      await context.route('**/*', r => r.request().url().startsWith('file:') ? r.continue() : r.abort());
      page.on('request', r => { if (!r.url().startsWith('file:')) external.push(r.url()); });
      page.on('pageerror', e => errors.push(e.message));
      page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
      await page.goto(pathToFileURL(html).href);
      await page.waitForSelector('[data-expense-id="RV-M2"]');
      await page.locator('input').fill('2026-03');
      const positive = await measure(page);
      requireHeaderContrast(positive.headers); requireLayout(positive);
      assert.deepEqual(positive.ids, ['RV-M2', 'RV-M1']);
      assert.deepEqual(positive.cells.map(c => c.text), ['Ngày', 'Nội dung', 'Số tiền', '2026-03-29', longText, '987654', '2026-03-02', 'Local light contrast probe', '123456']);
      assert(positive.labelLinked && positive.titleLinked && positive.tableLinked);
      assert.equal(positive.labelText, 'Lọc theo tháng'); assert.equal(positive.inputType, 'month');
      assert.deepEqual(positive.scopes, ['col', 'col', 'col']);
      assert(contrast(positive.inputColor, positive.inputBackground) >= 4.5);
      const focusMarch = await requireKeyboard(page);
      const screenshot = path.join(out, 'own-340-light.png');
      await page.screenshot({ path: screenshot, fullPage: true });
      await page.evaluate(() => { for (const th of document.querySelectorAll('th')) th.style.color = 'var(--cvf-surface)'; });
      const negative = await measure(page); let rejection = null;
      try { requireHeaderContrast(negative.headers); } catch (e) { assert.equal(e.name, 'AssertionError'); rejection = e.message; }
      assert(rejection?.startsWith('HEADER_TEXT_CONTRAST'), 'negative discriminates header defect');
      await page.evaluate(() => { for (const th of document.querySelectorAll('th')) th.style.removeProperty('color'); });
      requireHeaderContrast((await measure(page)).headers);
      await page.locator('input').fill('2026-04');
      const empty = await measure(page); assert.deepEqual(empty.ids, []); assert(empty.status?.startsWith('Không có khoản chi nào.')); requireLayout(empty);
      const focusEmpty = await requireKeyboard(page);
      await page.locator('input').fill('');
      const cleared = await measure(page); assert.deepEqual(cleared.ids, ['RV-F', 'RV-M2', 'RV-M1']); requireHeaderContrast(cleared.headers); requireLayout(cleared);
      assert.equal(hash(source), sourceHash); assert.equal(external.length, 0); assert.equal(errors.length, 0);
      report = { status: 'PASS', viewport: { width: 340, height: 844 }, profile: 'synthetic-light-default', sourceSha256: sourceHash, oracleSha256: hash(__filename), positive, headerRatios: positive.headers.map(h => contrast(h.color,h.bg)), focusMarch, focusEmpty, negative: { kind: 'DOM_ONLY_HEADER_SAME_AS_SURFACE', ratios: negative.headers.map(h => contrast(h.color,h.bg)), rejectedByAssertion: true, rejection }, restored: 'PASS', clearIds: cleared.ids, screenshot: { path: path.relative(root,screenshot).replace(/\\/g,'/'), sha256: hash(screenshot) }, externalRequests: 0, pageErrors: 0, browserVersion: browser.version(), independence: 'Own literals, IDs, fixture and contrast formula; imports actual component only. Source exposure disclosed; worker oracle not imported.' };
    } finally { await context.close(); }
  } finally { await browser.close(); }
  fs.writeFileSync(path.join(out,'probe-results.json'), JSON.stringify(report,null,2)+'\n');
  console.log(JSON.stringify({ status: report.status, headerRatios: report.headerRatios, negative: report.negative, inputHeight: report.positive.input.height, screenshot: report.screenshot }));
})().catch(e => { console.error(e.stack); process.exitCode = 1; });
